      "id": "F3",
      "name": "Least-privilege tool suite",
      "summary": "Curated tools (file read/write/edit, shell, code search, web, VCS, test runner, package manager) with permission scoping and audit logging.",
      "priority": "P0"
    },
    {
      "id": "F4",
      "name": "Agent-building Skills library",
      "summary": "Reusable, model-invoked playbooks in Agent-Skills format (SKILL.md + scripts) for scaffolding, tool design, prompt engineering, evals, quality gates, MCP, orchestration, memory, safety.",
      "priority": "P0"
    },
    {
      "id": "F5",
      "name": "MCP integration layer",
      "summary": "Standardized external capabilities via Model Context Protocol servers (filesystem, git/github, fetch, browser, database, memory) with a declarative manifest.",
      "priority": "P1"
