      "priority": "P0"
    },
    {
      "id": "F7",
      "name": "Subagent orchestration",
      "summary": "Spawns specialized subagents (researcher, architect, coder, reviewer, tester) with self-contained briefs and result synthesis.",
      "priority": "P1"
    },
