      "id": "F8",
      "name": "Context & memory management",
      "summary": "Plan file, scratchpad, external artifact store, and compaction policy to survive long builds within context limits.",
      "priority": "P1"
    },
    {
      "id": "F9",
      "name": "Evaluation harness",
      "summary": "Generates and runs an eval suite for every produced agent (task success, tool-call correctness, safety, regression) with a scoreboard.",
      "priority": "P0"
