cd /workspace/agentagent2 && python3 - <<'PY'
import json
schema=json.load(open("design/schemas/agent_design.schema.json"))
d=json.load(open("design/agentagent2.design.json"))
errors=[]

# top-level required
for k in schema["required"]:
    if k not in d: errors.append(f"missing top-level '{k}'")
# additionalProperties false
allowed=set(schema["properties"])
for k in d:
    if k not in allowed: errors.append(f"unexpected top-level '{k}'")

# identity
idr=schema["properties"]["identity"]["required"]
for k in idr:
    if k not in d["identity"]: errors.append(f"identity missing '{k}'")
if not d["identity"].get("success_criteria"): errors.append("identity.success_criteria empty")

# tools
perm_enum={"read","write","exec","network-read","network-write","orchestrate"}
safe_enum={"safe","guarded","privileged"}
for t in d["tools"]:
    for rk in ["name","purpose","permissions","safety"]:
        if rk not in t: errors.append(f"tool {t.get('name','?')} missing {rk}")
    for p in t.get("permissions",[]):
        if p not in perm_enum: errors.append(f"tool {t['name']} bad permission {p}")
    if t.get("safety") not in safe_enum: errors.append(f"tool {t['name']} bad safety {t.get('safety')}")

# style
lang_enum={"python","typescript","go","rust","bash"}
for k in ["core","languages"]:
    if k not in d["style"]: errors.append(f"style missing {k}")
for l in d["style"].get("languages",[]):
    if l not in lang_enum: errors.append(f"style bad language {l}")
if not d["style"].get("languages"): errors.append("style.languages empty")

# evaluation
ev=d["evaluation"]
if not ev.get("dimensions"): errors.append("evaluation.dimensions empty")
th=ev.get("thresholds",{})
for k in ["overall_min","safety_min"]:
    if k not in th: errors.append(f"thresholds missing {k}")
    else:
        v=th[k]
        if not (0<=v<=1): errors.append(f"threshold {k} out of range")

# safety
for k in ["permission_matrix","secrets_policy"]:
    if k not in d["safety"]: errors.append(f"safety missing {k}")

# mcp
for m in d.get("mcp",[]):
    for rk in ["name","capabilities","enabled_by_default"]:
        if rk not in m: errors.append(f"mcp {m.get('name','?')} missing {rk}")

if errors:
    print("SCHEMA CHECK: FAILED")
    for e in errors: print("  -",e)
else:
    print("SCHEMA CHECK: PASS — agentagent2.design.json satisfies agent_design.schema.json constraints")
    print(f"  tools={len(d['tools'])} skills={len(d['skills'])} mcp={len(d['mcp'])} langs={len(d['style']['languages'])}")
